CREATE TABLE users (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    email VARCHAR2(255 CHAR) NOT NULL, 
    display_name VARCHAR2(80 CHAR) NOT NULL, 
    password_hash VARCHAR2(255 CHAR) NOT NULL, 
    is_active BOOLEAN NOT NULL, 
    last_login_at DATE, 
    created_at DATE NOT NULL, 
    updated_at DATE NOT NULL, 
    PRIMARY KEY (id), 
    UNIQUE (email)
)

/

CREATE TABLE accounts (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    user_id INTEGER NOT NULL, 
    name VARCHAR2(40 CHAR) NOT NULL, 
    type VARCHAR2(16 CHAR) NOT NULL, 
    initial_balance_cents INTEGER NOT NULL, 
    sort_order INTEGER NOT NULL, 
    is_active BOOLEAN NOT NULL, 
    created_at DATE NOT NULL, 
    updated_at DATE NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
    CONSTRAINT uq_accounts_user_name UNIQUE (user_id, name)
)

/

CREATE INDEX ix_accounts_user ON accounts (user_id)

/

CREATE TABLE categories (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    user_id INTEGER NOT NULL, 
    name VARCHAR2(40 CHAR) NOT NULL, 
    kind VARCHAR2(16 CHAR) NOT NULL, 
    icon VARCHAR2(40 CHAR), 
    color VARCHAR2(16 CHAR), 
    sort_order INTEGER NOT NULL, 
    is_active BOOLEAN NOT NULL, 
    created_at DATE NOT NULL, 
    updated_at DATE NOT NULL, 
    PRIMARY KEY (id), 
    CONSTRAINT ck_categories_kind CHECK (kind IN ('expense', 'income')), 
    FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
    CONSTRAINT uq_categories_user_kind_name UNIQUE (user_id, kind, name)
)

/

CREATE INDEX ix_categories_user_kind ON categories (user_id, kind)

/

CREATE TABLE transactions (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    user_id INTEGER NOT NULL, 
    biz_date DATE NOT NULL, 
    occurred_at DATE NOT NULL, 
    amount_cents INTEGER NOT NULL, 
    direction VARCHAR2(3 CHAR) NOT NULL, 
    category_id INTEGER NOT NULL, 
    account_id INTEGER, 
    payee VARCHAR2(120 CHAR), 
    note CLOB, 
    external_id VARCHAR2(128 CHAR), 
    deleted_at DATE, 
    created_at DATE NOT NULL, 
    updated_at DATE NOT NULL, 
    PRIMARY KEY (id), 
    CONSTRAINT ck_txn_direction CHECK (direction IN ('out', 'in')), 
    CONSTRAINT ck_txn_amount_positive CHECK (amount_cents > 0), 
    FOREIGN KEY(account_id) REFERENCES accounts (id) ON DELETE SET NULL, 
    FOREIGN KEY(category_id) REFERENCES categories (id), 
    FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
    CONSTRAINT uq_txn_user_external UNIQUE (user_id, external_id)
)

/

CREATE INDEX ix_txn_user_category_date ON transactions (user_id, category_id, biz_date)

/

CREATE INDEX ix_txn_user_date ON transactions (user_id, biz_date)

